const CapacityReservationSchema = z
  .object({
    CapacityReservationId: StringSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'capacityReservationId' },
          description: 'The ID of the Capacity Reservation.',
        }),
    ).exactOptional(),
    OwnerId: StringSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'ownerId' },
          description:
            'The ID of the Amazon Web Services account that owns the Capacity Reservation.',
        }),
    ).exactOptional(),
    CapacityReservationArn: StringSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'capacityReservationArn' },
          description: 'The Amazon Resource Name (ARN) of the Capacity Reservation.',
        }),
    ).exactOptional(),
    AvailabilityZoneId: StringSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'availabilityZoneId' },
          description: 'The Availability Zone ID of the Capacity Reservation.',
        }),
    ).exactOptional(),
    InstanceType: StringSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'instanceType' },
          description: 'The type of instance for which the Capacity Reservation reserves capacity.',
        }),
    ).exactOptional(),
    InstancePlatform: CapacityReservationInstancePlatformSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'instancePlatform' },
          description:
            'The type of operating system for which the Capacity Reservation reserves capacity.',
        }),
    ).exactOptional(),
    AvailabilityZone: StringSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'availabilityZone' },
          description: 'The Availability Zone in which the capacity is reserved.',
        }),
    ).exactOptional(),
    Tenancy: CapacityReservationTenancySchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'tenancy' },
          description:
            '<p>Indicates the tenancy of the Capacity Reservation. A Capacity Reservation can have one of the following tenancy settings:</p> <ul> <li> <p> <code>default</code> - The Capacity Reservation is created on hardware that is shared with other Amazon Web Services accounts.</p> </li> <li> <p> <code>dedicated</code> - The Capacity Reservation is created on single-tenant hardware that is dedicated to a single Amazon Web Services account.</p> </li> </ul>',
        }),
    ).exactOptional(),
    TotalInstanceCount: IntegerSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'totalInstanceCount' },
          description:
            'The total number of instances for which the Capacity Reservation reserves capacity.',
        }),
    ).exactOptional(),
    AvailableInstanceCount: IntegerSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'availableInstanceCount' },
          description:
            'The remaining capacity. Indicates the number of instances that can be launched in the Capacity Reservation.',
        }),
    ).exactOptional(),
    EbsOptimized: BooleanSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'ebsOptimized' },
          description:
            "Indicates whether the Capacity Reservation supports EBS-optimized instances. This optimization provides dedicated throughput to Amazon EBS and an optimized configuration stack to provide optimal I/O performance. This optimization isn't available with all instance types. Additional usage charges apply when using an EBS- optimized instance.",
        }),
    ).exactOptional(),
    EphemeralStorage: BooleanSchema.and(
      z.any().openapi({ xml: { name: 'ephemeralStorage' }, description: ' <i>Deprecated.</i> ' }),
    ).exactOptional(),
    State: CapacityReservationStateSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'state' },
          description:
            '<p>The current state of the Capacity Reservation. A Capacity Reservation can be in one of the following states:</p> <ul> <li> <p> <code>active</code> - The Capacity Reservation is active and the capacity is available for your use.</p> </li> <li> <p> <code>expired</code> - The Capacity Reservation expired automatically at the date and time specified in your request. The reserved capacity is no longer available for your use.</p> </li> <li> <p> <code>cancelled</code> - The Capacity Reservation was cancelled. The reserved capacity is no longer available for your use.</p> </li> <li> <p> <code>pending</code> - The Capacity Reservation request was successful but the capacity provisioning is still pending.</p> </li> <li> <p> <code>failed</code> - The Capacity Reservation request has failed. A request might fail due to invalid request parameters, capacity constraints, or instance limit constraints. Failed requests are retained for 60 minutes.</p> </li> </ul>',
        }),
    ).exactOptional(),
    StartDate: MillisecondDateTimeSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'startDate' },
          description: 'The date and time at which the Capacity Reservation was started.',
        }),
    ).exactOptional(),
    EndDate: DateTimeSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'endDate' },
          description:
            "The date and time at which the Capacity Reservation expires. When a Capacity Reservation expires, the reserved capacity is released and you can no longer launch instances into it. The Capacity Reservation's state changes to <code>expired</code> when it reaches its end date and time.",
        }),
    ).exactOptional(),
    EndDateType: EndDateTypeSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'endDateType' },
          description:
            '<p>Indicates the way in which the Capacity Reservation ends. A Capacity Reservation can have one of the following end types:</p> <ul> <li> <p> <code>unlimited</code> - The Capacity Reservation remains active until you explicitly cancel it.</p> </li> <li> <p> <code>limited</code> - The Capacity Reservation expires automatically at a specified date and time.</p> </li> </ul>',
        }),
    ).exactOptional(),
    InstanceMatchCriteria: InstanceMatchCriteriaSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'instanceMatchCriteria' },
          description:
            '<p>Indicates the type of instance launches that the Capacity Reservation accepts. The options include:</p> <ul> <li> <p> <code>open</code> - The Capacity Reservation accepts all instances that have matching attributes (instance type, platform, and Availability Zone). Instances that have matching attributes launch into the Capacity Reservation automatically without specifying any additional parameters.</p> </li> <li> <p> <code>targeted</code> - The Capacity Reservation only accepts instances that have matching attributes (instance type, platform, and Availability Zone), and explicitly target the Capacity Reservation. This ensures that only permitted instances can use the reserved capacity. </p> </li> </ul>',
        }),
    ).exactOptional(),
    CreateDate: DateTimeSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'createDate' },
          description: 'The date and time at which the Capacity Reservation was created.',
        }),
    ).exactOptional(),
    Tags: TagListSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'tagSet' },
          description: 'Any tags assigned to the Capacity Reservation.',
        }),
    ).exactOptional(),
    OutpostArn: OutpostArnSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'outpostArn' },
          description:
            'The Amazon Resource Name (ARN) of the Outpost on which the Capacity Reservation was created.',
        }),
    ).exactOptional(),
    CapacityReservationFleetId: StringSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'capacityReservationFleetId' },
          description:
            'The ID of the Capacity Reservation Fleet to which the Capacity Reservation belongs. Only valid for Capacity Reservations that were created by a Capacity Reservation Fleet.',
        }),
    ).exactOptional(),
    PlacementGroupArn: PlacementGroupArnSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'placementGroupArn' },
          description:
            'The Amazon Resource Name (ARN) of the cluster placement group in which the Capacity Reservation was created. For more information, see <a href="https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/cr-cpg.html"> Capacity Reservations for cluster placement groups</a> in the <i>Amazon EC2 User Guide</i>.',
        }),
    ).exactOptional(),
    CapacityAllocations: CapacityAllocationsSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'capacityAllocationSet' },
          description: 'Information about instance capacity usage.',
        }),
    ).exactOptional(),
  })
  .openapi({ description: 'Describes a Capacity Reservation.', required: [] })
  .openapi('CapacityReservation')

