const IpamPoolCidrSchema = z
  .object({
    Cidr: StringSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'cidr' },
          description:
            'The CIDR provisioned to the IPAM pool. A CIDR is a representation of an IP address and its associated network mask (or netmask) and refers to a range of IP addresses. An IPv4 CIDR example is <code>10.24.34.0/23</code>. An IPv6 CIDR example is <code>2001:DB8::/32</code>.',
        }),
    ).exactOptional(),
    State: IpamPoolCidrStateSchema.and(
      z.any().openapi({ xml: { name: 'state' }, description: 'The state of the CIDR.' }),
    ).exactOptional(),
    FailureReason: IpamPoolCidrFailureReasonSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'failureReason' },
          description: 'Details related to why an IPAM pool CIDR failed to be provisioned.',
        }),
    ).exactOptional(),
    IpamPoolCidrId: IpamPoolCidrIdSchema.and(
      z.any().openapi({ xml: { name: 'ipamPoolCidrId' }, description: 'The IPAM pool CIDR ID.' }),
    ).exactOptional(),
    NetmaskLength: IntegerSchema.and(
      z
        .any()
        .openapi({
          xml: { name: 'netmaskLength' },
          description:
            'The netmask length of the CIDR you\'d like to provision to a pool. Can be used for provisioning Amazon-provided IPv6 CIDRs to top-level pools and for provisioning CIDRs to pools with source pools. Cannot be used to provision BYOIP CIDRs to top-level pools. "NetmaskLength" or "Cidr" is required.',
        }),
    ).exactOptional(),
  })
  .openapi({ description: 'A CIDR provisioned to an IPAM pool.', required: [] })
  .openapi('IpamPoolCidr')

