export const getActionAttachNetworkInterfaceRoute = createRoute({
  method: 'get',
  path: '/#Action=AttachNetworkInterface',
  description: 'Attaches a network interface to an instance.',
  operationId: 'GET_AttachNetworkInterface',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['EnaSrdEnabled', ['EnaSrdSpecification']],
          ['EnaSrdUdpSpecification', ['EnaSrdSpecification']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          DeviceIndex: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            )
            .openapi({
              param: {
                name: 'DeviceIndex',
                in: 'query',
                required: true,
                description: 'The index of the device for the network interface attachment.',
                schema: { type: 'integer' },
              },
            }),
          DryRun: z
            .stringbool()
            .exactOptional()
            .openapi({
              param: {
                name: 'DryRun',
                in: 'query',
                required: false,
                description:
                  'Checks whether you have the required permissions for the action, without actually making the request, and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.',
                schema: { type: 'boolean' },
              },
            }),
          InstanceId: z
            .string()
            .openapi({
              param: {
                name: 'InstanceId',
                in: 'query',
                required: true,
                description: 'The ID of the instance.',
                schema: { type: 'string' },
              },
            }),
          NetworkInterfaceId: z
            .string()
            .openapi({
              param: {
                name: 'NetworkInterfaceId',
                in: 'query',
                required: true,
                description: 'The ID of the network interface.',
                schema: { type: 'string' },
              },
            }),
          NetworkCardIndex: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            )
            .exactOptional()
            .openapi({
              param: {
                name: 'NetworkCardIndex',
                in: 'query',
                required: false,
                description:
                  'The index of the network card. Some instance types support multiple network cards. The primary network interface must be assigned to network card index 0. The default is network card index 0.',
                schema: { type: 'integer' },
              },
            }),
          EnaSrdSpecification: z
            .object({
              EnaSrdEnabled: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  BooleanSchema,
                )
                .and(
                  z
                    .any()
                    .openapi({
                      description:
                        'Indicates whether ENA Express is enabled for the network interface.',
                    }),
                )
                .exactOptional(),
              EnaSrdUdpSpecification: z
                .object({
                  EnaSrdUdpEnabled: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      BooleanSchema,
                    )
                    .and(
                      z
                        .any()
                        .openapi({
                          description:
                            'Indicates whether UDP traffic uses ENA Express. To specify this setting, you must first enable ENA Express.',
                        }),
                    )
                    .exactOptional(),
                })
                .openapi({
                  description:
                    'ENA Express is compatible with both TCP and UDP transport protocols. When it’s enabled, TCP traffic automatically uses it. However, some UDP-based applications are designed to handle network packets that are out of order, without a need for retransmission, such as live video broadcasting or other near-real-time applications. For UDP traffic, you can specify whether to use ENA Express, based on your application environment needs.',
                  required: [],
                })
                .and(
                  z
                    .any()
                    .openapi({ description: 'Configures ENA Express for UDP network traffic.' }),
                )
                .exactOptional(),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'EnaSrdSpecification',
                in: 'query',
                required: false,
                description:
                  'Configures ENA Express for the network interface that this action attaches to the instance.',
                schema: {
                  type: 'object',
                  properties: {
                    EnaSrdEnabled: {
                      allOf: [
                        { $ref: '#/components/schemas/Boolean' },
                        {
                          description:
                            'Indicates whether ENA Express is enabled for the network interface.',
                        },
                      ],
                    },
                    EnaSrdUdpSpecification: {
                      allOf: [
                        {
                          type: 'object',
                          properties: {
                            EnaSrdUdpEnabled: {
                              allOf: [
                                { $ref: '#/components/schemas/Boolean' },
                                {
                                  description:
                                    'Indicates whether UDP traffic uses ENA Express. To specify this setting, you must first enable ENA Express.',
                                },
                              ],
                            },
                          },
                          description:
                            'ENA Express is compatible with both TCP and UDP transport protocols. When it’s enabled, TCP traffic automatically uses it. However, some UDP-based applications are designed to handle network packets that are out of order, without a need for retransmission, such as live video broadcasting or other near-real-time applications. For UDP traffic, you can specify whether to use ENA Express, based on your application environment needs.',
                        },
                        { description: 'Configures ENA Express for UDP network traffic.' },
                      ],
                    },
                  },
                  description:
                    '<p>ENA Express uses Amazon Web Services Scalable Reliable Datagram (SRD) technology to increase the maximum bandwidth used per stream and minimize tail latency of network traffic between EC2 instances. With ENA Express, you can communicate between two EC2 instances in the same subnet within the same account, or in different accounts. Both sending and receiving instances must have ENA Express enabled.</p> <p>To improve the reliability of network packet delivery, ENA Express reorders network packets on the receiving end by default. However, some UDP-based applications are designed to handle network packets that are out of order to reduce the overhead for packet delivery at the network layer. When ENA Express is enabled, you can specify whether UDP network traffic uses it.</p>',
                },
              },
              description:
                '<p>ENA Express uses Amazon Web Services Scalable Reliable Datagram (SRD) technology to increase the maximum bandwidth used per stream and minimize tail latency of network traffic between EC2 instances. With ENA Express, you can communicate between two EC2 instances in the same subnet within the same account, or in different accounts. Both sending and receiving instances must have ENA Express enabled.</p> <p>To improve the reliability of network packet delivery, ENA Express reorders network packets on the receiving end by default. However, some UDP-based applications are designed to handle network packets that are out of order to reduce the overhead for packet delivery at the network layer. When ENA Express is enabled, you can specify whether UDP network traffic uses it.</p>',
              required: [],
            }),
          Action: z
            .literal('AttachNetworkInterface')
            .openapi({
              param: {
                name: 'Action',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['AttachNetworkInterface'] },
              },
            }),
          Version: z
            .literal('2016-11-15')
            .openapi({
              param: {
                name: 'Version',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['2016-11-15'] },
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: AttachNetworkInterfaceResultSchema } },
    },
  },
})

