export const getActionBundleInstanceRoute = createRoute({
  method: 'get',
  path: '/#Action=BundleInstance',
  description:
    '<p>Bundles an Amazon instance store-backed Windows instance.</p> <p>During bundling, only the root device volume (C:\\) is bundled. Data on other instance store volumes is not preserved.</p> <note> <p>This action is not applicable for Linux/Unix instances or Windows instances that are backed by Amazon EBS.</p> </note>',
  operationId: 'GET_BundleInstance',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([['S3', ['Storage']]])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          InstanceId: z
            .string()
            .openapi({
              param: {
                name: 'InstanceId',
                in: 'query',
                required: true,
                description:
                  '<p>The ID of the instance to bundle.</p> <p>Type: String</p> <p>Default: None</p> <p>Required: Yes</p>',
                schema: { type: 'string' },
              },
            }),
          Storage: z
            .object({
              S3: S3StorageSchema.and(
                z.any().openapi({ description: 'An Amazon S3 storage location.' }),
              ).exactOptional(),
            })
            .openapi({
              param: {
                name: 'Storage',
                in: 'query',
                required: true,
                description:
                  'The bucket in which to store the AMI. You can specify a bucket that you already own or a new bucket that Amazon EC2 creates on your behalf. If you specify a bucket that belongs to someone else, Amazon EC2 returns an error.',
                schema: {
                  type: 'object',
                  properties: {
                    S3: {
                      allOf: [
                        { $ref: '#/components/schemas/S3Storage' },
                        { description: 'An Amazon S3 storage location.' },
                      ],
                    },
                  },
                  description: 'Describes the storage location for an instance store-backed AMI.',
                },
              },
              description: 'Describes the storage location for an instance store-backed AMI.',
              required: [],
            }),
          DryRun: z
            .stringbool()
            .exactOptional()
            .openapi({
              param: {
                name: 'DryRun',
                in: 'query',
                required: false,
                description:
                  'Checks whether you have the required permissions for the action, without actually making the request, and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.',
                schema: { type: 'boolean' },
              },
            }),
          Action: z
            .literal('BundleInstance')
            .openapi({
              param: {
                name: 'Action',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['BundleInstance'] },
              },
            }),
          Version: z
            .literal('2016-11-15')
            .openapi({
              param: {
                name: 'Version',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['2016-11-15'] },
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: BundleInstanceResultSchema } },
    },
  },
})

