export const getActionDeleteNetworkAclEntryRoute = createRoute({
  method: 'get',
  path: '/#Action=DeleteNetworkAclEntry',
  description:
    'Deletes the specified ingress or egress entry (rule) from the specified network ACL.',
  operationId: 'GET_DeleteNetworkAclEntry',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      DryRun: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'DryRun',
            in: 'query',
            required: false,
            description:
              'Checks whether you have the required permissions for the action, without actually making the request, and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.',
            schema: { type: 'boolean' },
          },
        }),
      Egress: z
        .stringbool()
        .openapi({
          param: {
            name: 'Egress',
            in: 'query',
            required: true,
            description: 'Indicates whether the rule is an egress rule.',
            schema: { type: 'boolean' },
          },
        }),
      NetworkAclId: z
        .string()
        .openapi({
          param: {
            name: 'NetworkAclId',
            in: 'query',
            required: true,
            description: 'The ID of the network ACL.',
            schema: { type: 'string' },
          },
        }),
      RuleNumber: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'RuleNumber',
            in: 'query',
            required: true,
            description: 'The rule number of the entry to delete.',
            schema: { type: 'integer' },
          },
        }),
      Action: z
        .literal('DeleteNetworkAclEntry')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['DeleteNetworkAclEntry'] },
          },
        }),
      Version: z
        .literal('2016-11-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2016-11-15'] },
          },
        }),
    }),
  },
  responses: { 200: { description: 'Success' } },
})

