export const getActionGetFlowLogsIntegrationTemplateRoute = createRoute({
  method: 'get',
  path: '/#Action=GetFlowLogsIntegrationTemplate',
  description:
    '<p>Generates a CloudFormation template that streamlines and automates the integration of VPC flow logs with Amazon Athena. This make it easier for you to query and gain insights from VPC flow logs data. Based on the information that you provide, we configure resources in the template to do the following:</p> <ul> <li> <p>Create a table in Athena that maps fields to a custom log format</p> </li> <li> <p>Create a Lambda function that updates the table with new partitions on a daily, weekly, or monthly basis</p> </li> <li> <p>Create a table partitioned between two timestamps in the past</p> </li> <li> <p>Create a set of named queries in Athena that you can use to get started quickly</p> </li> </ul>',
  operationId: 'GET_GetFlowLogsIntegrationTemplate',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([['AthenaIntegrations', ['IntegrateService']]])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          DryRun: z
            .stringbool()
            .exactOptional()
            .openapi({
              param: {
                name: 'DryRun',
                in: 'query',
                required: false,
                description:
                  'Checks whether you have the required permissions for the action, without actually making the request, and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.',
                schema: { type: 'boolean' },
              },
            }),
          FlowLogId: z
            .string()
            .openapi({
              param: {
                name: 'FlowLogId',
                in: 'query',
                required: true,
                description: 'The ID of the flow log.',
                schema: { type: 'string' },
              },
            }),
          ConfigDeliveryS3DestinationArn: z
            .string()
            .openapi({
              param: {
                name: 'ConfigDeliveryS3DestinationArn',
                in: 'query',
                required: true,
                description:
                  'To store the CloudFormation template in Amazon S3, specify the location in Amazon S3.',
                schema: { type: 'string' },
              },
            }),
          IntegrateService: z
            .object({
              AthenaIntegrations: AthenaIntegrationsSetSchema.and(
                ((schema) =>
                  z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                  z.any(),
                ).openapi({
                  xml: { name: 'AthenaIntegration' },
                  description: 'Information about the integration with Amazon Athena.',
                }),
              ).exactOptional(),
            })
            .openapi({
              param: {
                name: 'IntegrateService',
                in: 'query',
                required: true,
                description: 'Information about the service integration.',
                schema: {
                  type: 'object',
                  properties: {
                    AthenaIntegrations: {
                      allOf: [
                        { $ref: '#/components/schemas/AthenaIntegrationsSet' },
                        {
                          xml: { name: 'AthenaIntegration' },
                          description: 'Information about the integration with Amazon Athena.',
                        },
                      ],
                    },
                  },
                  description: 'Describes service integrations with VPC Flow logs.',
                },
              },
              description: 'Describes service integrations with VPC Flow logs.',
              required: [],
            }),
          Action: z
            .literal('GetFlowLogsIntegrationTemplate')
            .openapi({
              param: {
                name: 'Action',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['GetFlowLogsIntegrationTemplate'] },
              },
            }),
          Version: z
            .literal('2016-11-15')
            .openapi({
              param: {
                name: 'Version',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['2016-11-15'] },
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: GetFlowLogsIntegrationTemplateResultSchema } },
    },
  },
})

