export const getActionImportKeyPairRoute = createRoute({
  method: 'get',
  path: '/#Action=ImportKeyPair',
  description:
    '<p>Imports the public key from an RSA or ED25519 key pair that you created with a third-party tool. Compare this with <a>CreateKeyPair</a>, in which Amazon Web Services creates the key pair and gives the keys to you (Amazon Web Services keeps a copy of the public key). With ImportKeyPair, you create the key pair and give Amazon Web Services just the public key. The private key is never transferred between you and Amazon Web Services.</p> <p>For more information about key pairs, see <a href="https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-key-pairs.html">Amazon EC2 key pairs</a> in the <i>Amazon Elastic Compute Cloud User Guide</i>.</p>',
  operationId: 'GET_ImportKeyPair',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      DryRun: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'DryRun',
            in: 'query',
            required: false,
            description:
              'Checks whether you have the required permissions for the action, without actually making the request, and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.',
            schema: { type: 'boolean' },
          },
        }),
      KeyName: z
        .string()
        .openapi({
          param: {
            name: 'KeyName',
            in: 'query',
            required: true,
            description: 'A unique name for the key pair.',
            schema: { type: 'string' },
          },
        }),
      PublicKeyMaterial: z
        .string()
        .openapi({
          param: {
            name: 'PublicKeyMaterial',
            in: 'query',
            required: true,
            description:
              'The public key. For API calls, the text must be base64-encoded. For command line tools, base64 encoding is performed for you.',
            schema: { type: 'string' },
          },
        }),
      TagSpecification: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            TagSpecificationSchema.and(
              ((schema) =>
                z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                z.any(),
              ).openapi({ xml: { name: 'item' } }),
            ),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'TagSpecification',
            in: 'query',
            required: false,
            description: 'The tags to apply to the imported key pair.',
            schema: {
              type: 'array',
              items: {
                allOf: [
                  { $ref: '#/components/schemas/TagSpecification' },
                  { xml: { name: 'item' } },
                ],
              },
            },
          },
        }),
      Action: z
        .literal('ImportKeyPair')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['ImportKeyPair'] },
          },
        }),
      Version: z
        .literal('2016-11-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2016-11-15'] },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success', content: { 'text/xml': { schema: ImportKeyPairResultSchema } } },
  },
})

