export const getActionModifyTransitGatewayRoute = createRoute({
  method: 'get',
  path: '/#Action=ModifyTransitGateway',
  description:
    'Modifies the specified transit gateway. When you modify a transit gateway, the modified options are applied to new transit gateway attachments only. Your existing transit gateway attachments are not modified.',
  operationId: 'GET_ModifyTransitGateway',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['AddTransitGatewayCidrBlocks', ['Options']],
          ['RemoveTransitGatewayCidrBlocks', ['Options']],
          ['VpnEcmpSupport', ['Options']],
          ['DnsSupport', ['Options']],
          ['AutoAcceptSharedAttachments', ['Options']],
          ['DefaultRouteTableAssociation', ['Options']],
          ['AssociationDefaultRouteTableId', ['Options']],
          ['DefaultRouteTablePropagation', ['Options']],
          ['PropagationDefaultRouteTableId', ['Options']],
          ['AmazonSideAsn', ['Options']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          TransitGatewayId: z
            .string()
            .openapi({
              param: {
                name: 'TransitGatewayId',
                in: 'query',
                required: true,
                description: 'The ID of the transit gateway.',
                schema: { type: 'string' },
              },
            }),
          Description: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'Description',
                in: 'query',
                required: false,
                description: 'The description for the transit gateway.',
                schema: { type: 'string' },
              },
            }),
          Options: z
            .object({
              AddTransitGatewayCidrBlocks: TransitGatewayCidrBlockStringListSchema.and(
                z
                  .any()
                  .openapi({
                    description:
                      'Adds IPv4 or IPv6 CIDR blocks for the transit gateway. Must be a size /24 CIDR block or larger for IPv4, or a size /64 CIDR block or larger for IPv6.',
                  }),
              ).exactOptional(),
              RemoveTransitGatewayCidrBlocks: TransitGatewayCidrBlockStringListSchema.and(
                z.any().openapi({ description: 'Removes CIDR blocks for the transit gateway.' }),
              ).exactOptional(),
              VpnEcmpSupport: VpnEcmpSupportValueSchema.and(
                z
                  .any()
                  .openapi({
                    description: 'Enable or disable Equal Cost Multipath Protocol support.',
                  }),
              ).exactOptional(),
              DnsSupport: DnsSupportValueSchema.and(
                z.any().openapi({ description: 'Enable or disable DNS support.' }),
              ).exactOptional(),
              AutoAcceptSharedAttachments: AutoAcceptSharedAttachmentsValueSchema.and(
                z
                  .any()
                  .openapi({
                    description: 'Enable or disable automatic acceptance of attachment requests.',
                  }),
              ).exactOptional(),
              DefaultRouteTableAssociation: DefaultRouteTableAssociationValueSchema.and(
                z
                  .any()
                  .openapi({
                    description:
                      'Enable or disable automatic association with the default association route table.',
                  }),
              ).exactOptional(),
              AssociationDefaultRouteTableId: TransitGatewayRouteTableIdSchema.and(
                z.any().openapi({ description: 'The ID of the default association route table.' }),
              ).exactOptional(),
              DefaultRouteTablePropagation: DefaultRouteTablePropagationValueSchema.and(
                z
                  .any()
                  .openapi({
                    description:
                      'Enable or disable automatic propagation of routes to the default propagation route table.',
                  }),
              ).exactOptional(),
              PropagationDefaultRouteTableId: TransitGatewayRouteTableIdSchema.and(
                z.any().openapi({ description: 'The ID of the default propagation route table.' }),
              ).exactOptional(),
              AmazonSideAsn: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  LongSchema,
                )
                .and(
                  z
                    .any()
                    .openapi({
                      description:
                        '<p>A private Autonomous System Number (ASN) for the Amazon side of a BGP session. The range is 64512 to 65534 for 16-bit ASNs and 4200000000 to 4294967294 for 32-bit ASNs.</p> <p>The modify ASN operation is not allowed on a transit gateway with active BGP sessions. You must first delete all transit gateway attachments that have BGP configured prior to modifying the ASN on the transit gateway.</p>',
                    }),
                )
                .exactOptional(),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'Options',
                in: 'query',
                required: false,
                description: 'The options to modify.',
                schema: {
                  type: 'object',
                  properties: {
                    AddTransitGatewayCidrBlocks: {
                      allOf: [
                        { $ref: '#/components/schemas/TransitGatewayCidrBlockStringList' },
                        {
                          description:
                            'Adds IPv4 or IPv6 CIDR blocks for the transit gateway. Must be a size /24 CIDR block or larger for IPv4, or a size /64 CIDR block or larger for IPv6.',
                        },
                      ],
                    },
                    RemoveTransitGatewayCidrBlocks: {
                      allOf: [
                        { $ref: '#/components/schemas/TransitGatewayCidrBlockStringList' },
                        { description: 'Removes CIDR blocks for the transit gateway.' },
                      ],
                    },
                    VpnEcmpSupport: {
                      allOf: [
                        { $ref: '#/components/schemas/VpnEcmpSupportValue' },
                        { description: 'Enable or disable Equal Cost Multipath Protocol support.' },
                      ],
                    },
                    DnsSupport: {
                      allOf: [
                        { $ref: '#/components/schemas/DnsSupportValue' },
                        { description: 'Enable or disable DNS support.' },
                      ],
                    },
                    AutoAcceptSharedAttachments: {
                      allOf: [
                        { $ref: '#/components/schemas/AutoAcceptSharedAttachmentsValue' },
                        {
                          description:
                            'Enable or disable automatic acceptance of attachment requests.',
                        },
                      ],
                    },
                    DefaultRouteTableAssociation: {
                      allOf: [
                        { $ref: '#/components/schemas/DefaultRouteTableAssociationValue' },
                        {
                          description:
                            'Enable or disable automatic association with the default association route table.',
                        },
                      ],
                    },
                    AssociationDefaultRouteTableId: {
                      allOf: [
                        { $ref: '#/components/schemas/TransitGatewayRouteTableId' },
                        { description: 'The ID of the default association route table.' },
                      ],
                    },
                    DefaultRouteTablePropagation: {
                      allOf: [
                        { $ref: '#/components/schemas/DefaultRouteTablePropagationValue' },
                        {
                          description:
                            'Enable or disable automatic propagation of routes to the default propagation route table.',
                        },
                      ],
                    },
                    PropagationDefaultRouteTableId: {
                      allOf: [
                        { $ref: '#/components/schemas/TransitGatewayRouteTableId' },
                        { description: 'The ID of the default propagation route table.' },
                      ],
                    },
                    AmazonSideAsn: {
                      allOf: [
                        { $ref: '#/components/schemas/Long' },
                        {
                          description:
                            '<p>A private Autonomous System Number (ASN) for the Amazon side of a BGP session. The range is 64512 to 65534 for 16-bit ASNs and 4200000000 to 4294967294 for 32-bit ASNs.</p> <p>The modify ASN operation is not allowed on a transit gateway with active BGP sessions. You must first delete all transit gateway attachments that have BGP configured prior to modifying the ASN on the transit gateway.</p>',
                        },
                      ],
                    },
                  },
                  description: 'The transit gateway options.',
                },
              },
              description: 'The transit gateway options.',
              required: [],
            }),
          DryRun: z
            .stringbool()
            .exactOptional()
            .openapi({
              param: {
                name: 'DryRun',
                in: 'query',
                required: false,
                description:
                  'Checks whether you have the required permissions for the action, without actually making the request, and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.',
                schema: { type: 'boolean' },
              },
            }),
          Action: z
            .literal('ModifyTransitGateway')
            .openapi({
              param: {
                name: 'Action',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['ModifyTransitGateway'] },
              },
            }),
          Version: z
            .literal('2016-11-15')
            .openapi({
              param: {
                name: 'Version',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['2016-11-15'] },
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: ModifyTransitGatewayResultSchema } },
    },
  },
})

