export const getActionReplaceIamInstanceProfileAssociationRoute = createRoute({
  method: 'get',
  path: '/#Action=ReplaceIamInstanceProfileAssociation',
  description:
    "<p>Replaces an IAM instance profile for the specified running instance. You can use this action to change the IAM instance profile that's associated with an instance without having to disassociate the existing IAM instance profile first.</p> <p>Use <a>DescribeIamInstanceProfileAssociations</a> to get the association ID.</p>",
  operationId: 'GET_ReplaceIamInstanceProfileAssociation',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['Arn', ['IamInstanceProfile']],
          ['Name', ['IamInstanceProfile']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          IamInstanceProfile: z
            .object({
              Arn: StringSchema.and(
                ((schema) =>
                  z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                  z.any(),
                ).openapi({
                  xml: { name: 'arn' },
                  description: 'The Amazon Resource Name (ARN) of the instance profile.',
                }),
              ).exactOptional(),
              Name: StringSchema.and(
                ((schema) =>
                  z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                  z.any(),
                ).openapi({
                  xml: { name: 'name' },
                  description: 'The name of the instance profile.',
                }),
              ).exactOptional(),
            })
            .openapi({
              param: {
                name: 'IamInstanceProfile',
                in: 'query',
                required: true,
                description: 'The IAM instance profile.',
                schema: {
                  type: 'object',
                  properties: {
                    Arn: {
                      allOf: [
                        { $ref: '#/components/schemas/String' },
                        {
                          xml: { name: 'arn' },
                          description: 'The Amazon Resource Name (ARN) of the instance profile.',
                        },
                      ],
                    },
                    Name: {
                      allOf: [
                        { $ref: '#/components/schemas/String' },
                        { xml: { name: 'name' }, description: 'The name of the instance profile.' },
                      ],
                    },
                  },
                  description: 'Describes an IAM instance profile.',
                },
              },
              description: 'Describes an IAM instance profile.',
              required: [],
            }),
          AssociationId: z
            .string()
            .openapi({
              param: {
                name: 'AssociationId',
                in: 'query',
                required: true,
                description: 'The ID of the existing IAM instance profile association.',
                schema: { type: 'string' },
              },
            }),
          Action: z
            .literal('ReplaceIamInstanceProfileAssociation')
            .openapi({
              param: {
                name: 'Action',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['ReplaceIamInstanceProfileAssociation'] },
              },
            }),
          Version: z
            .literal('2016-11-15')
            .openapi({
              param: {
                name: 'Version',
                in: 'query',
                required: true,
                schema: { type: 'string', enum: ['2016-11-15'] },
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: ReplaceIamInstanceProfileAssociationResultSchema } },
    },
  },
})

