export const getActionReportInstanceStatusRoute = createRoute({
  method: 'get',
  path: '/#Action=ReportInstanceStatus',
  description:
    '<p>Submits feedback about the status of an instance. The instance must be in the <code>running</code> state. If your experience with the instance differs from the instance status returned by <a>DescribeInstanceStatus</a>, use <a>ReportInstanceStatus</a> to report your experience with the instance. Amazon EC2 collects this information to improve the accuracy of status checks.</p> <p>Use of this action does not change the value returned by <a>DescribeInstanceStatus</a>.</p>',
  operationId: 'GET_ReportInstanceStatus',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      Description: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'Description',
            in: 'query',
            required: false,
            description: 'Descriptive text about the health state of your instance.',
            schema: { type: 'string' },
          },
        }),
      DryRun: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'DryRun',
            in: 'query',
            required: false,
            description:
              'Checks whether you have the required permissions for the action, without actually making the request, and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.',
            schema: { type: 'boolean' },
          },
        }),
      EndTime: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'EndTime',
            in: 'query',
            required: false,
            description: 'The time at which the reported instance health state ended.',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      InstanceId: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            InstanceIdSchema.and(
              ((schema) =>
                z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                z.any(),
              ).openapi({ xml: { name: 'InstanceId' } }),
            ),
          ),
        )
        .openapi({
          param: {
            name: 'InstanceId',
            in: 'query',
            required: true,
            description: 'The instances.',
            schema: {
              type: 'array',
              items: {
                allOf: [
                  { $ref: '#/components/schemas/InstanceId' },
                  { xml: { name: 'InstanceId' } },
                ],
              },
            },
          },
        }),
      ReasonCode: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            ReportInstanceReasonCodesSchema.and(
              ((schema) =>
                z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                z.any(),
              ).openapi({ xml: { name: 'item' } }),
            ),
          ),
        )
        .openapi({
          param: {
            name: 'ReasonCode',
            in: 'query',
            required: true,
            description:
              '<p>The reason codes that describe the health state of your instance.</p> <ul> <li> <p> <code>instance-stuck-in-state</code>: My instance is stuck in a state.</p> </li> <li> <p> <code>unresponsive</code>: My instance is unresponsive.</p> </li> <li> <p> <code>not-accepting-credentials</code>: My instance is not accepting my credentials.</p> </li> <li> <p> <code>password-not-available</code>: A password is not available for my instance.</p> </li> <li> <p> <code>performance-network</code>: My instance is experiencing performance problems that I believe are network related.</p> </li> <li> <p> <code>performance-instance-store</code>: My instance is experiencing performance problems that I believe are related to the instance stores.</p> </li> <li> <p> <code>performance-ebs-volume</code>: My instance is experiencing performance problems that I believe are related to an EBS volume.</p> </li> <li> <p> <code>performance-other</code>: My instance is experiencing performance problems.</p> </li> <li> <p> <code>other</code>: [explain using the description parameter]</p> </li> </ul>',
            schema: {
              type: 'array',
              items: {
                allOf: [
                  { $ref: '#/components/schemas/ReportInstanceReasonCodes' },
                  { xml: { name: 'item' } },
                ],
              },
            },
          },
        }),
      StartTime: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'StartTime',
            in: 'query',
            required: false,
            description: 'The time at which the reported instance health state began.',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      Status: z
        .enum(['ok', 'impaired'])
        .openapi({
          param: {
            name: 'Status',
            in: 'query',
            required: true,
            description: 'The status of all instances listed.',
            schema: { type: 'string', enum: ['ok', 'impaired'] },
          },
        }),
      Action: z
        .literal('ReportInstanceStatus')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['ReportInstanceStatus'] },
          },
        }),
      Version: z
        .literal('2016-11-15')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2016-11-15'] },
          },
        }),
    }),
  },
  responses: { 200: { description: 'Success' } },
})

